std::mutex resource_lock;
int shared_data = 0;

void safe_update(int val) {
    // RAII guarantees release upon scope exit
    std::lock_guard<std::mutex> lock(resource_lock);

    // Critical section
    shared_data += val;

} // lock released here

std::atomic<int> safe_counter{0};

void atomic_increment() {
    // Guaranteed single, non-interruptible operation
    safe_counter++; 

    // CAS (Compare-And-Swap) operation
    int expected = safe_counter.load();
    int desired = expected + 1;
    safe_counter.compare_exchange_weak(expected, desired);
}
